/* ============================================
   CSS Custom Properties (Design Tokens)
   ============================================ */
:root {
  /* Colors */
  --color-primary: #667eea;
  --color-primary-dark: #5568d3;
  --color-primary-light: #818cf8;
  --color-secondary: #764ba2;
  --color-accent: #f59e0b;

  --color-text-primary: #1f2937;
  --color-text-secondary: #6b7280;
  --color-text-light: #9ca3af;

  --color-background: #ffffff;
  --color-surface: #f9fafb;
  --color-border: #e5e7eb;

  --color-success: #10b981;
  --color-success-bg: #d1fae5;
  --color-warning: #f59e0b;
  --color-warning-bg: #fef3c7;
  --color-error: #ef4444;
  --color-error-bg: #fee2e2;
  --color-info: #3b82f6;
  --color-info-bg: #dbeafe;

  /* Typography */
  --font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans',
                      'Hiragino Kaku Gothic ProN', 'Noto Sans JP', sans-serif;
  --font-size-xs: 0.75rem;    /* 12px */
  --font-size-sm: 0.875rem;   /* 14px */
  --font-size-base: 1rem;     /* 16px */
  --font-size-lg: 1.125rem;   /* 18px */
  --font-size-xl: 1.25rem;    /* 20px */
  --font-size-2xl: 1.5rem;    /* 24px */
  --font-size-3xl: 2rem;      /* 32px */
  --font-size-4xl: 3rem;      /* 48px */

  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  --line-height-tight: 1.25;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.75;

  /* Spacing */
  --spacing-xs: 0.25rem;   /* 4px */
  --spacing-sm: 0.5rem;    /* 8px */
  --spacing-md: 1rem;      /* 16px */
  --spacing-lg: 1.5rem;    /* 24px */
  --spacing-xl: 2rem;      /* 32px */
  --spacing-2xl: 3rem;     /* 48px */
  --spacing-3xl: 4rem;     /* 64px */

  /* Border Radius */
  --radius-sm: 0.375rem;   /* 6px */
  --radius-md: 0.5rem;     /* 8px */
  --radius-lg: 0.75rem;    /* 12px */
  --radius-xl: 1rem;       /* 16px */
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);

  /* Transitions */
  --transition-fast: 150ms ease-in-out;
  --transition-base: 250ms ease-in-out;
  --transition-slow: 350ms ease-in-out;

  /* Z-index layers */
  --z-dropdown: 1000;
  --z-sticky: 1020;
  --z-fixed: 1030;
  --z-modal-backdrop: 1040;
  --z-modal: 1050;
  --z-popover: 1060;
  --z-tooltip: 1070;
}

/* ============================================
   CSS Reset & Base Styles
   ============================================ */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  min-height: 100vh;
  padding: var(--spacing-lg);
}

/* ============================================
   Accessibility - Visually Hidden
   ============================================ */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ============================================
   Skip Links for Accessibility
   ============================================ */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: var(--spacing-sm) var(--spacing-md);
  text-decoration: none;
  z-index: var(--z-tooltip);
}

.skip-link:focus {
  top: 0;
}

/* ============================================
   Container & Layout
   ============================================ */
.container {
  max-width: 1200px;
  margin: 0 auto;
}

/* ============================================
   Header
   ============================================ */
.site-header {
  text-align: center;
  color: white;
  margin-bottom: var(--spacing-2xl);
  padding: var(--spacing-xl) var(--spacing-md);
}

.brand-name {
  font-size: clamp(var(--font-size-2xl), 5vw, var(--font-size-4xl));
  font-weight: var(--font-weight-normal);
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-sm);
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
}

.subtitle {
  font-size: clamp(var(--font-size-base), 3vw, var(--font-size-xl));
  font-weight: var(--font-weight-normal);
  opacity: 0.95;
}

/* ============================================
   Main Content
   ============================================ */
.main-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  margin-bottom: var(--spacing-2xl);
}

@media (max-width: 768px) {
  .main-content {
    grid-template-columns: 1fr;
  }
}

/* ============================================
   Form Section & Info Panel
   ============================================ */
.form-section,
.info-panel {
  background: var(--color-background);
  border-radius: var(--radius-xl);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-xl);
  transition: transform var(--transition-base);
}

.form-section:hover,
.info-panel:hover {
  transform: translateY(-2px);
}

.form-section h2,
.info-panel h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-lg);
  font-weight: var(--font-weight-semibold);
  font-size: var(--font-size-xl);
}

/* ============================================
   Form Styles
   ============================================ */
.form-group {
  margin-bottom: var(--spacing-lg);
}

.form-label {
  display: block;
  margin-bottom: var(--spacing-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

.required {
  color: var(--color-error);
  font-weight: var(--font-weight-bold);
}

.form-input,
.form-select {
  width: 100%;
  padding: var(--spacing-md) var(--spacing-md);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-base);
  font-family: inherit;
  color: var(--color-text-primary);
  background-color: var(--color-background);
  transition: all var(--transition-base);
}

.form-input:hover,
.form-select:hover {
  border-color: var(--color-primary-light);
}

.form-input:focus,
.form-select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.form-input[aria-invalid="true"],
.form-select[aria-invalid="true"] {
  border-color: var(--color-error);
}

.form-input[aria-invalid="true"]:focus,
.form-select[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1);
}

/* Error Messages */
.error-message {
  display: none;
  color: var(--color-error);
  font-size: var(--font-size-sm);
  margin-top: var(--spacing-xs);
  font-weight: var(--font-weight-medium);
}

.error-message:not(:empty) {
  display: block;
}

/* ============================================
   Call Button
   ============================================ */
.call-button {
  width: 100%;
  padding: var(--spacing-md) var(--spacing-xl);
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  color: white;
  border: none;
  border-radius: var(--radius-md);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: all var(--transition-base);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  margin-top: var(--spacing-xl);
  position: relative;
  overflow: hidden;
}

.call-button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-secondary) 100%);
  opacity: 0;
  transition: opacity var(--transition-base);
}

.call-button:hover::before {
  opacity: 1;
}

.call-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(102, 126, 234, 0.4);
}

.call-button:active {
  transform: translateY(0);
}

.call-button:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.call-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.call-button:disabled::before {
  opacity: 0;
}

.button-icon,
#buttonText {
  position: relative;
  z-index: 1;
}

.button-icon {
  font-size: var(--font-size-2xl);
}

/* Loading Spinner */
.loading-spinner {
  display: none;
  width: 20px;
  height: 20px;
  border: 3px solid rgba(255, 255, 255, 0.3);
  border-top-color: white;
  border-radius: var(--radius-full);
  animation: spin 0.8s linear infinite;
  position: relative;
  z-index: 1;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.call-button[aria-busy="true"] .loading-spinner {
  display: block;
}

.call-button.calling .button-icon {
  animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(0.95);
  }
}

/* ============================================
   Status Messages
   ============================================ */
.status {
  margin-top: var(--spacing-lg);
  padding: var(--spacing-md);
  border-radius: var(--radius-md);
  text-align: center;
  font-weight: var(--font-weight-medium);
  font-size: var(--font-size-sm);
  display: none;
  animation: slideIn var(--transition-base);
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.status.active {
  display: block;
}

.status.info {
  background-color: var(--color-info-bg);
  color: var(--color-info);
  border: 1px solid var(--color-info);
}

.status.success {
  background-color: var(--color-success-bg);
  color: var(--color-success);
  border: 1px solid var(--color-success);
}

.status.error {
  background-color: var(--color-error-bg);
  color: var(--color-error);
  border: 1px solid var(--color-error);
}

/* ============================================
   Info Panel
   ============================================ */
.instruction-list,
.note-list {
  margin-left: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.instruction-list li,
.note-list li {
  margin-bottom: var(--spacing-md);
  line-height: var(--line-height-relaxed);
  color: var(--color-text-secondary);
}

.note-box {
  background-color: var(--color-warning-bg);
  border-left: 4px solid var(--color-warning);
  padding: var(--spacing-lg);
  border-radius: var(--radius-md);
  margin-top: var(--spacing-lg);
}

.note-title {
  color: #92400e;
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-semibold);
  margin-bottom: var(--spacing-md);
}

.note-list {
  margin-left: var(--spacing-lg);
  margin-bottom: 0;
}

/* ============================================
   Footer
   ============================================ */
.site-footer {
  text-align: center;
  padding: var(--spacing-lg);
  color: white;
}

.footer-text {
  opacity: 0.9;
  font-size: var(--font-size-sm);
}

/* ============================================
   Focus Styles for Accessibility
   ============================================ */
*:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* ============================================
   Utility Classes
   ============================================ */
.text-center {
  text-align: center;
}

.mt-0 { margin-top: 0; }
.mt-1 { margin-top: var(--spacing-xs); }
.mt-2 { margin-top: var(--spacing-sm); }
.mt-3 { margin-top: var(--spacing-md); }
.mt-4 { margin-top: var(--spacing-lg); }

.mb-0 { margin-bottom: 0; }
.mb-1 { margin-bottom: var(--spacing-xs); }
.mb-2 { margin-bottom: var(--spacing-sm); }
.mb-3 { margin-bottom: var(--spacing-md); }
.mb-4 { margin-bottom: var(--spacing-lg); }

/* ============================================
   Print Styles
   ============================================ */
@media print {
  body {
    background: white;
    color: black;
  }

  .call-button,
  .loading-spinner {
    display: none;
  }
}

/* ============================================
   High Contrast Mode Support
   ============================================ */
@media (prefers-contrast: high) {
  :root {
    --color-border: #000;
    --color-text-primary: #000;
  }
}

/* ============================================
   Reduced Motion Support
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

input.content:
/**
 * United Arrows Demo - Voice Call Application
 *
 * This application enables browser-based voice calls using Twilio Voice SDK v2
 * and integrates with OpenAI Realtime API for AI-powered customer support.
 *
 * @version 1.0.0
 */

'use strict';

// ============================================
// Constants & Configuration
// ============================================
const CONFIG = {
  API_ENDPOINTS: {
    TOKEN: '/api/token'
  },
  TWILIO: {
    LOG_LEVEL: 1,
    CODEC_PREFERENCES: ['opus', 'pcmu']
  },
  VALIDATION: {
    EMAIL_PATTERN: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  }
};

const STATUS_TYPES = {
  INFO: 'info',
  SUCCESS: 'success',
  ERROR: 'error'
};

const CALL_STATES = {
  IDLE: 'idle',
  INITIALIZING: 'initializing',
  CONNECTING: 'connecting',
  ACTIVE: 'active',
  ENDING: 'ending'
};

// ============================================
// State Management
// ============================================
const appState = {
  device: null,
  currentCall: null,
  callState: CALL_STATES.IDLE,
  elements: {}
};

// ============================================
// DOM Element References
// ============================================
const DOM_SELECTORS = {
  form: '#contactForm',
  callButton: '#callButton',
  buttonText: '#buttonText',
  status: '#status',
  nameInput: '#name',
  emailInput: '#email',
  requirementSelect: '#requirement',
  nameError: '#name-error',
  emailError: '#email-error',
  requirementError: '#requirement-error'
};

// ============================================
// Initialization
// ============================================

/**
 * Initialize the application when DOM is ready
 */
document.addEventListener('DOMContentLoaded', () => {
  try {
    // Check if Twilio SDK is loaded
    if (typeof Twilio === 'undefined') {
      console.error('Twilio SDK is not loaded');
      showAlert('エラー: Twilio SDKの読み込みに失敗しました。ページを再読み込みしてください。');
      return;
    }

    console.log('Twilio SDK loaded successfully');

    // Initialize DOM elements
    initializeElements();

    // Setup event listeners
    setupEventListeners();

    console.log('Application initialized successfully');
  } catch (error) {
    console.error('Application initialization failed:', error);
    showAlert('アプリケーションの初期化に失敗しました。');
  }
});

/**
 * Initialize DOM element references
 */
function initializeElements() {
  for (const [key, selector] of Object.entries(DOM_SELECTORS)) {
    const element = document.querySelector(selector);
    if (!element) {
      throw new Error(`Required element not found: ${selector}`);
    }
    appState.elements[key] = element;
  }
}

/**
 * Setup event listeners
 */
function setupEventListeners() {
  appState.elements.form.addEventListener('submit', handleFormSubmit);

  // Add input validation listeners
  appState.elements.nameInput.addEventListener('blur', () => validateField('name'));
  appState.elements.emailInput.addEventListener('blur', () => validateField('email'));
  appState.elements.requirementSelect.addEventListener('change', () => validateField('requirement'));

  // Cleanup on page unload
  window.addEventListener('beforeunload', cleanup);
}

// ============================================
// Twilio Device Management
// ============================================

/**
 * Initialize Twilio Device
 * @returns {Promise<boolean>} Success status
 */
async function initializeDevice() {
  try {
    updateCallState(CALL_STATES.INITIALIZING);

    const identity = appState.elements.nameInput.value || 'user';

    console.log('Requesting token from server...');
    const response = await fetch(CONFIG.API_ENDPOINTS.TOKEN, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ identity })
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Token request failed: ${response.status} - ${errorText}`);
    }

    const data = await response.json();
    console.log('Token received');

    if (!data.token) {
      throw new Error('Token not found in response');
    }

    // Create Twilio Device
    console.log('Creating Twilio Device...');
    appState.device = new Twilio.Device(data.token, {
      logLevel: CONFIG.TWILIO.LOG_LEVEL,
      codecPreferences: CONFIG.TWILIO.CODEC_PREFERENCES
    });

    // Setup device event handlers
    setupDeviceEventHandlers();

    console.log('Registering device...');
    await appState.device.register();
    console.log('Device registered successfully');

    return true;
  } catch (error) {
    console.error('Failed to initialize device:', error);
    updateStatus(`デバイス初期化失敗: ${error.message}`, STATUS_TYPES.ERROR);
    updateCallState(CALL_STATES.IDLE);
    return false;
  }
}

/**
 * Setup Twilio Device event handlers
 */
function setupDeviceEventHandlers() {
  appState.device.on('registered', () => {
    console.log('Device registered');
    updateStatus('デバイスが登録されました', STATUS_TYPES.SUCCESS);
  });

  appState.device.on('error', (error) => {
    console.error('Device error:', error);
    updateStatus(`デバイスエラー: ${error.message}`, STATUS_TYPES.ERROR);
    resetCallButton();
    updateCallState(CALL_STATES.IDLE);
  });

  appState.device.on('incoming', (call) => {
    console.log('Incoming call');
    appState.currentCall = call;
    setupCallEventHandlers(call);
  });
}

// ============================================
// Call Management
// ============================================

/**
 * Make an outbound call
 */
async function makeCall() {
  try {
    // Initialize device if not already initialized
    if (!appState.device) {
      updateStatus('デバイスを初期化しています...', STATUS_TYPES.INFO);
      const initialized = await initializeDevice();
      if (!initialized) {
        return;
      }
    }

    // Prepare call parameters
    const params = {
      requirement: appState.elements.requirementSelect.value,
      name: appState.elements.nameInput.value,
      email: appState.elements.emailInput.value
    };

    updateCallState(CALL_STATES.CONNECTING);
    updateStatus('通話を開始しています...', STATUS_TYPES.INFO);
    setButtonLoading(true);

    // Make the call
    appState.currentCall = await appState.device.connect({ params });
    setupCallEventHandlers(appState.currentCall);

  } catch (error) {
    console.error('Failed to make call:', error);
    updateStatus(`通話の開始に失敗しました: ${error.message}`, STATUS_TYPES.ERROR);
    resetCallButton();
    updateCallState(CALL_STATES.IDLE);
  }
}

/**
 * Setup call event handlers
 * @param {Object} call - Twilio Call object
 */
function setupCallEventHandlers(call) {
  call.on('accept', () => {
    console.log('Call accepted');
    updateCallState(CALL_STATES.ACTIVE);
    updateStatus('通話中...', STATUS_TYPES.SUCCESS);
    appState.elements.buttonText.textContent = '通話を終了';
    appState.elements.callButton.classList.remove('calling');
    setButtonLoading(false);
  });

  call.on('disconnect', () => {
    console.log('Call disconnected');
    updateCallState(CALL_STATES.IDLE);
    updateStatus('通話が終了しました', STATUS_TYPES.INFO);
    appState.currentCall = null;
    resetCallButton();
  });

  call.on('cancel', () => {
    console.log('Call cancelled');
    updateCallState(CALL_STATES.IDLE);
    updateStatus('通話がキャンセルされました', STATUS_TYPES.INFO);
    appState.currentCall = null;
    resetCallButton();
  });

  call.on('reject', () => {
    console.log('Call rejected');
    updateCallState(CALL_STATES.IDLE);
    updateStatus('通話が拒否されました', STATUS_TYPES.ERROR);
    appState.currentCall = null;
    resetCallButton();
  });

  call.on('error', (error) => {
    console.error('Call error:', error);
    updateCallState(CALL_STATES.IDLE);
    updateStatus(`通話エラー: ${error.message}`, STATUS_TYPES.ERROR);
    appState.currentCall = null;
    resetCallButton();
  });
}

/**
 * Hang up the current call
 */
function hangUp() {
  if (appState.currentCall) {
    updateCallState(CALL_STATES.ENDING);
    appState.currentCall.disconnect();
  }
}

// ============================================
// Form Validation
// ============================================

/**
 * Validate a specific form field
 * @param {string} fieldName - Name of the field to validate
 * @returns {boolean} Validation result
 */
function validateField(fieldName) {
  const field = appState.elements[`${fieldName}Input`] || appState.elements[`${fieldName}Select`];
  const errorElement = appState.elements[`${fieldName}Error`];

  if (!field) return true;

  let isValid = true;
  let errorMessage = '';

  // Check if field is empty
  if (!field.value.trim()) {
    isValid = false;
    errorMessage = 'この項目は必須です';
  }
  // Email-specific validation
  else if (fieldName === 'email' && !CONFIG.VALIDATION.EMAIL_PATTERN.test(field.value)) {
    isValid = false;
    errorMessage = '有効なメールアドレスを入力してください';
  }

  // Update UI
  field.setAttribute('aria-invalid', !isValid);
  if (errorElement) {
    errorElement.textContent = errorMessage;
  }

  return isValid;
}

/**
 * Validate the entire form
 * @returns {boolean} Validation result
 */
function validateForm() {
  const nameValid = validateField('name');
  const emailValid = validateField('email');
  const requirementValid = validateField('requirement');

  return nameValid && emailValid && requirementValid;
}

// ============================================
// Event Handlers
// ============================================

/**
 * Handle form submission
 * @param {Event} e - Submit event
 */
async function handleFormSubmit(e) {
  e.preventDefault();

  // Validate form
  if (!validateForm()) {
    updateStatus('すべての項目を正しく入力してください', STATUS_TYPES.ERROR);
    return;
  }

  // Handle call state
  if (appState.currentCall && appState.callState === CALL_STATES.ACTIVE) {
    // If already in call, hang up
    hangUp();
  } else if (appState.callState === CALL_STATES.IDLE) {
    // Otherwise, make a new call
    await makeCall();
  }
}

// ============================================
// UI Updates
// ============================================

/**
 * Update call state
 * @param {string} newState - New call state
 */
function updateCallState(newState) {
  appState.callState = newState;
  console.log('Call state changed to:', newState);
}

/**
 * Update status message
 * @param {string} message - Status message
 * @param {string} type - Status type (info, success, error)
 */
function updateStatus(message, type) {
  const statusDiv = appState.elements.status;
  statusDiv.textContent = message;
  statusDiv.className = `status active ${type}`;
}

/**
 * Set button loading state
 * @param {boolean} isLoading - Loading state
 */
function setButtonLoading(isLoading) {
  const button = appState.elements.callButton;
  button.setAttribute('aria-busy', isLoading);
  button.disabled = isLoading;

  if (isLoading) {
    button.classList.add('calling');
    appState.elements.buttonText.textContent = '接続中...';
  }
}

/**
 * Reset call button to initial state
 */
function resetCallButton() {
  const button = appState.elements.callButton;
  button.setAttribute('aria-busy', 'false');
  button.disabled = false;
  button.classList.remove('calling');
  appState.elements.buttonText.textContent = '電話で問い合わせる';
}

/**
 * Show browser alert
 * @param {string} message - Alert message
 */
function showAlert(message) {
