                type: 'object',
                properties: {
                  name: {
                    type: 'string',
                    description: '商品名（部分一致）'
                  },
                  category: {
                    type: 'string',
                    description: 'カテゴリ（トップス、ボトムス、アウター）'
                  },
                  color: {
                    type: 'string',
                    description: 'カラー'
                  },
                  size: {
                    type: 'string',
                    description: 'サイズ'
                  }
                }
              }
            }
          ],
          tool_choice: 'auto'
        }
      };

      openAiWs.send(JSON.stringify(sessionConfig));
    });

