/**
 * Environment Variable Validation Utility
 *
 * Validates required environment variables and exits process if any are missing.
 */

const requiredEnvVars = [
  'TWILIO_ACCOUNT_SID',
  'TWILIO_AUTH_TOKEN',
  'TWILIO_API_KEY',
  'TWILIO_API_SECRET',
  'TWILIO_TWIML_APP_SID',
  'OPENAI_API_KEY'
];

/**
 * Validate all required environment variables
 * @throws {Error} Exits process if validation fails
 */
function validateEnv() {
  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error('\n❌ ERROR: Missing required environment variables:');
    missingVars.forEach(varName => console.error(`   - ${varName}`));
    console.error('\nPlease create a .env file based on .env.example and fill in all required values.\n');
    process.exit(1);
  }

  console.log('✅ All required environment variables are set');
}

/**
 * Validate specific environment variables (for endpoints)
 * @param {string[]} vars - Array of variable names to validate
 * @returns {string[]} Array of missing variable names
 */
function validateSpecificVars(vars) {
  return vars.filter(varName => !process.env[varName]);
}

module.exports = {
  validateEnv,
  validateSpecificVars,
  requiredEnvVars
};

