    case 'input_audio_buffer.committed':
      console.log('Audio committed');
      break;

    case 'response.done':
      console.log('AI response completed');
      console.log('shouldTerminateAfterResponse flag:', state.shouldTerminateAfterResponse);

      // Terminate call if flag is set
      if (state.shouldTerminateAfterResponse) {
        console.log('Scheduling call termination...');

        // Clear any existing timer
        if (state.terminationTimer) {
          console.log('Clearing previous termination timer');
          clearTimeout(state.terminationTimer);
        }

        // Set new timer - wait for final response to complete
        state.terminationTimer = setTimeout(() => {
          console.log('Closing connections now...');
          if (openAiWs && openAiWs.readyState === WebSocket.OPEN) {
            openAiWs.close();
          }
          if (twilioWs && twilioWs.readyState === WebSocket.OPEN) {
            twilioWs.close();
          }
        }, 5000); // Increased to 5 seconds to allow final exchange
      }
      break;

    case 'error':
      console.error('OpenAI error:', message);
      break;
  }
}

/**
 * Handle function call
 * @param {Object} item - Function call item
 * @param {Object} openAiWs - OpenAI WebSocket connection
 * @param {string} customerName - Customer name
 * @param {Object} state - Connection state
 */
function handleFunctionCall(item, openAiWs, customerName, state) {
  const { call_id, name, arguments: args } = item;

  console.log('Handling function call:', name, 'with args:', args);

  // Parse arguments safely
  let params = {};
  try {
    if (args) {
      if (typeof args === 'string') {
        params = args.trim() ? JSON.parse(args) : {};
      } else {
        params = args;
      }
    }
  } catch (parseError) {
    console.error('Error parsing arguments:', parseError);
    return;
  }

  console.log('Parsed params:', params);

  if (name === 'search_inventory') {
    handleSearchInventory(call_id, params, openAiWs);
  } else if (name === 'reserve_product') {
    console.log('Executing reserve_product...');
    handleReserveProduct(call_id, params, openAiWs, () => {
      console.log('Setting shouldTerminateAfterResponse flag to true');
      state.shouldTerminateAfterResponse = true;
    });
  }
}

module.exports = {
  connectToOpenAI,
  createSessionConfig,
  createGreetingMessage
};

/**
 * AI Instructions Configuration
 *
 * Defines AI assistant instructions based on inquiry type.
 */

/**
 * Build AI instructions based on customer information and inquiry type
 * @param {string} customerName - Customer name
 * @param {string} requirement - Inquiry type
 * @returns {string} Complete AI instructions
 */
function buildInstructions(customerName, requirement) {
  const baseInstructions = `あなたはUnited Arrowsのカスタマーサービス担当者です。
お客様のお名前は${customerName}様です。
お問い合わせ種別: ${requirement}

`;

  const requirementInstructions = {
    '商品について': `商品に関するお問い合わせに丁寧に対応してください。

【対応フロー】
1. お客様がお探しの商品について詳細をお聞きする（商品名、カラー、サイズなど）
2. search_inventory関数を使用して在庫を確認する
3. 在庫がある場合、必ず「取り置きをされますか？」と確認する
4. お客様が取り置きを希望される場合、reserve_product関数を使用して取り置き処理を行う
5. 取り置きが完了したら、お客様に確認内容をお伝えし、「本日はUnited Arrowsをご利用いただきありがとうございました。それでは失礼いたします。」と丁寧に会話を終了する

在庫がない場合は、その旨をお伝えして、他の商品を提案するか、会話を終了してください。`,

    '配送について': `配送に関するお問い合わせに対応してください。
配送状況、配送方法、配送料金などについて案内してください。`,

    '返品・交換について': `返品・交換に関するお問い合わせに対応してください。
返品条件、交換手続きなどについて案内してください。`,

    'その他': `お客様のお問い合わせ内容を丁寧にお聞きして、適切に対応してください。`
  };

  const specificInstructions = requirementInstructions[requirement] || requirementInstructions['その他'];

  const closingInstructions = `\n\n日本語で自然で丁寧な会話を心がけてください。
まず、お客様に挨拶をして、どのようなご用件かお伺いしてください。`;

  return baseInstructions + specificInstructions + closingInstructions;
}

module.exports = {
  buildInstructions
};

